		"body.go.tmpl",
		"auth.go.tmpl",
		"config_cmd.go.tmpl",
		"auth_cmd.go.tmpl",
	}

	for _, name := range templates {
		data, err := templateFS.ReadFile("templates/" + name)
		if err != nil {
