			return c
		}
	}
	mapping := map[string]string{
		"next_cursor":        "cursor",
		"end_cursor":         "after",
		"next_page_token":    "page_token",
		"continuation_token": "cursor",
	}
	if p, ok := mapping[bodyField]; ok {
