func isEmptyArray(body []byte) bool {
	body = bytes.TrimSpace(body)
	if len(body) < 2 {
		return false
	}
	if body[0] == '[' {
		var arr []json.RawMessage
		if json.Unmarshal(body, &arr) == nil && len(arr) == 0 {
			return true
		}
	}
	if body[0] == '{' {
		var obj map[string]json.RawMessage
		if json.Unmarshal(body, &obj) == nil {
			for _, key := range []string{"data", "results", "items", "records", "entries"} {
				if raw, ok := obj[key]; ok {
					var arr []json.RawMessage
					if json.Unmarshal(raw, &arr) == nil && len(arr) == 0 {
						return true
					}
				}
			}
		}
	}
	return false
}

func mergePaginatedBodies(pages [][]byte) []byte {
	if len(pages) == 0 {
		return nil
	}
	if len(pages) == 1 {
		return pages[0]
	}
	var merged []json.RawMessage
	for _, p := range pages {
		p = bytes.TrimSpace(p)
		if len(p) == 0 {
			continue
		}
		if p[0] == '[' {
			var chunk []json.RawMessage
			if err := json.Unmarshal(p, &chunk); err != nil {
				return pages[len(pages)-1]
			}
			merged = append(merged, chunk...)
			continue
		}
		if p[0] == '{' {
			var obj map[string]json.RawMessage
			if json.Unmarshal(p, &obj) == nil {
				for _, key := range []string{"data", "results", "items", "records", "entries"} {
					if raw, ok := obj[key]; ok {
						var chunk []json.RawMessage
						if json.Unmarshal(raw, &chunk) == nil {
							merged = append(merged, chunk...)
							goto nextPage
						}
					}
				}
			}
			return pages[len(pages)-1]
		}
		return pages[len(pages)-1]
	nextPage:
	}
	out, err := json.Marshal(merged)
	if err != nil {
		return pages[len(pages)-1]
	}
	return out
}

func parseNextLink(linkHeader string) string {
	if linkHeader == "" {
		return ""
	}
	for _, raw := range strings.Split(linkHeader, ",") {
		part := strings.TrimSpace(raw)
		lower := strings.ToLower(part)
		if !strings.Contains(lower, `rel="next"`) && !strings.Contains(lower, `rel='next'`) && !strings.Contains(lower, "rel=next") {
			continue
		}
		start := strings.Index(part, "<")
		end := strings.Index(part, ">")
		if start < 0 || end <= start {
			continue
		}
		return part[start+1 : end]
	}
	return ""
}

